    faqInventory:      { en: 'Inventory Turnover Ratio', es: 'Ratio de Rotación de Inventario' },
    faqPeakHour:       { en: 'Peak Hour Analysis', es: 'Análisis de Horas Pico' },
    faqRetention:      { en: 'Customer Retention Rate', es: 'Tasa de Retención de Clientes' },
    faqFoodWaste:      { en: 'Food Waste (Weight & Monetary)', es: 'Desperdicio de Alimentos (Peso y Monetario)' },
