  // ─── Privacy ──────────────────────────────────────────────────────────────
  privacy: {
    legal:             { en: 'Legal', es: 'Legal' },
    title:             { en: 'Privacy Policy', es: 'Política de Privacidad' },
    lastUpdated:       { en: 'Last Updated:', es: 'Última Actualización:' },
    intro:             { en: "At Ecometricus by Us+AI Bureau, we are committed to protecting your privacy and the confidentiality of your property's data. This Privacy Policy explains what information we collect, how we use it, and the rights you have over your data.", es: 'En Ecometricus por Us+AI Bureau, estamos comprometidos a proteger tu privacidad y la confidencialidad de los datos de tu propiedad. Esta Política de Privacidad explica qué información recopilamos, cómo la usamos y los derechos que tienes sobre tus datos.' },
    infoWeCollect:     { en: 'Information We Collect', es: 'Información que Recopilamos' },
    howWeUse:          { en: 'How We Use Your Information', es: 'Cómo Usamos tu Información' },
    dataConfidentiality:{ en: 'Data Confidentiality', es: 'Confidencialidad de Datos' },
    dataSecurity:      { en: 'Data Security', es: 'Seguridad de Datos' },
    dataOwnership:     { en: 'Data Ownership', es: 'Propiedad de Datos' },
    cookies:           { en: 'Cookies & Tracking', es: 'Cookies y Rastreo' },
    changesToPolicy:   { en: 'Changes to This Policy', es: 'Cambios a esta Política' },
    contactSection:    { en: 'Contact', es: 'Contacto' },
    // Section content
    infoWeCollect1:    { en: 'Account information such as your name, email address, property name, and role when you register.', es: 'Información de la cuenta como tu nombre, correo electrónico, nombre de la propiedad y rol al registrarte.' },
    infoWeCollect2:    { en: 'F&B operational data you voluntarily input into the platform — food waste weights, outlet metrics, and ESG figures.', es: 'Datos operativos de F&B que ingresas voluntariamente en la plataforma — pesos de desperdicio de alimentos, métricas de outlet y cifras ESG.' },
    infoWeCollect3:    { en: 'Usage data including pages visited, features used, session duration, and device/browser type for improving the platform.', es: 'Datos de uso incluyendo páginas visitadas, funciones utilizadas, duración de sesión y tipo de dispositivo/navegador para mejorar la plataforma.' },
    infoWeCollect4:    { en: 'Assessment responses submitted through our sustainability questionnaire.', es: 'Respuestas de evaluación enviadas a través de nuestro cuestionario de sostenibilidad.' },
    howWeUse1:         { en: 'To provide, operate, and improve the Ecometricus platform and its AI-powered features.', es: 'Para proporcionar, operar y mejorar la plataforma Ecometricus y sus funciones impulsadas por IA.' },
    howWeUse2:         { en: 'To generate sustainability reports, ESG metrics, and operational insights personalized to your property.', es: 'Para generar reportes de sostenibilidad, métricas ESG e insights operativos personalizados para tu propiedad.' },
    howWeUse3:         { en: 'To communicate platform updates, new features, and relevant sustainability insights.', es: 'Para comunicar actualizaciones de la plataforma, nuevas funciones e insights de sostenibilidad relevantes.' },
    howWeUse4:         { en: 'To comply with legal obligations and enforce our Terms of Service.', es: 'Para cumplir con obligaciones legales y hacer cumplir nuestros Términos de Servicio.' },
    dataConfidentialityDesc: { en: "All information provided through Ecometricus is strictly confidential. Data shared by your property is used solely for analytical and operational purposes within your account. We do not sell, transfer, or disclose your data to third parties except as required by law or with your explicit consent. Each property's data is logically isolated and accessible only to authorized users within that account.", es: 'Toda la información proporcionada a través de Ecometricus es estrictamente confidencial. Los datos compartidos por tu propiedad se utilizan únicamente con fines analíticos y operativos dentro de tu cuenta. No vendemos, transferimos ni divulgamos tus datos a terceros excepto cuando lo exija la ley o con tu consentimiento explícito. Los datos de cada propiedad están lógicamente aislados y accesibles solo para usuarios autorizados dentro de esa cuenta.' },
    dataSecurityDesc:  { en: 'We use industry-standard security measures including TLS/HTTPS encryption in transit, role-based access controls, and secure cloud infrastructure. API connections to your existing systems (PMS, POS, CRM) are read-only and use encrypted tokens. No sensitive credentials are stored in plain text. We are committed to maintaining the integrity and security of all data entrusted to us.', es: 'Utilizamos medidas de seguridad estándar de la industria incluyendo cifrado TLS/HTTPS en tránsito, controles de acceso basados en roles e infraestructura en la nube segura. Las conexiones API a tus sistemas existentes (PMS, POS, CRM) son de solo lectura y utilizan tokens cifrados. No se almacenan credenciales sensibles en texto plano. Estamos comprometidos a mantener la integridad y seguridad de todos los datos que se nos confían.' },
    dataOwnershipDesc: { en: 'You retain full ownership and control of all data you input into Ecometricus. You may request an export or deletion of your data at any time by contacting our support team. Upon account termination, your data will be securely purged from our systems within 30 days unless retention is required by applicable law.', es: 'Conservas la propiedad y el control total de todos los datos que ingresas en Ecometricus. Puedes solicitar una exportación o eliminación de tus datos en cualquier momento contactando a nuestro equipo de soporte. Tras la terminación de la cuenta, tus datos se eliminarán de forma segura de nuestros sistemas dentro de 30 días a menos que la retención sea requerida por la ley aplicable.' },
    cookiesDesc:       { en: 'We use essential cookies to keep you logged in and maintain your session. We may use analytics tools to understand aggregate platform usage. We do not use advertising trackers or sell data to ad networks. You can manage cookie preferences through your browser settings.', es: 'Usamos cookies esenciales para mantener tu sesión iniciada. Podemos usar herramientas de análisis para entender el uso agregado de la plataforma. No usamos rastreadores publicitarios ni vendemos datos a redes publicitarias. Puedes gestionar las preferencias de cookies a través de la configuración de tu navegador.' },
    changesToPolicyDesc:{ en: 'We may update this Privacy Policy from time to time. When we do, we will revise the "Last Updated" date and notify you via email or an in-app notice. Continued use of the platform after changes constitutes your acceptance of the revised policy.', es: 'Podemos actualizar esta Política de Privacidad de vez en cuando. Al hacerlo, revisaremos la fecha de "Última Actualización" y te notificaremos por correo o un aviso en la aplicación. El uso continuo de la plataforma después de los cambios constituye tu aceptación de la política revisada.' },
    contactDesc:       { en: 'If you have questions about this Privacy Policy or how your data is handled, please reach out to our team through the Contact page or directly at the email address on file.', es: 'Si tienes preguntas sobre esta Política de Privacidad o cómo se manejan tus datos, comunícate con nuestro equipo a través de la página de Contacto o directamente al correo electrónico registrado.' },
  },

