    acceptance:        { en: 'Acceptance of Terms', es: 'Aceptación de Términos' },
    platformUse:       { en: 'Platform Use & Eligibility', es: 'Uso de la Plataforma y Elegibilidad' },
    permittedUse:      { en: 'Permitted Use', es: 'Uso Permitido' },
