    dataAccuracy:      { en: 'Data Accuracy', es: 'Precisión de Datos' },
    availability:      { en: 'Availability & Uptime', es: 'Disponibilidad y Tiempo de Actividad' },
    liability:         { en: 'Limitation of Liability', es: 'Limitación de Responsabilidad' },
    termination:       { en: 'Termination', es: 'Terminación' },
    changesToTerms:    { en: 'Changes to Terms', es: 'Cambios a los Términos' },
    governingLaw:      { en: 'Governing Law', es: 'Ley Aplicable' },
    // Section content
    acceptanceDesc:    { en: 'By accessing or using Ecometricus, you agree to be bound by these Terms of Service and our Privacy Policy. If you do not agree with any part of these terms, you may not access or use the platform. These terms apply to all users including administrators, supervisors, managers, and staff.', es: 'Al acceder o usar Ecometricus, aceptas estar sujeto a estos Términos de Servicio y nuestra Política de Privacidad. Si no estás de acuerdo con alguna parte de estos términos, no puedes acceder ni usar la plataforma. Estos términos se aplican a todos los usuarios incluyendo administradores, supervisores, gerentes y personal.' },
    platformUse1:      { en: 'You must be at least 18 years old and represent a legitimate hospitality or F&B business to use Ecometricus.', es: 'Debes tener al menos 18 años y representar un negocio legítimo de hotelería o F&B para usar Ecometricus.' },
    platformUse2:      { en: 'You are responsible for maintaining the confidentiality of your account credentials and for all activity under your account.', es: 'Eres responsable de mantener la confidencialidad de las credenciales de tu cuenta y de toda la actividad bajo tu cuenta.' },
    platformUse3:      { en: 'You agree not to share your login credentials or allow unauthorized persons to access your account.', es: 'Aceptas no compartir tus credenciales de inicio de sesión ni permitir que personas no autorizadas accedan a tu cuenta.' },
    platformUse4:      { en: "Each property subscription is for the use of that property's authorized personnel only.", es: 'Cada suscripción de propiedad es para el uso del personal autorizado de esa propiedad únicamente.' },
    permittedUse1:     { en: "Use the platform to track, analyze, and report on your property's F&B sustainability and operational metrics.", es: 'Usa la plataforma para rastrear, analizar y reportar las métricas de sostenibilidad y operativas de F&B de tu propiedad.' },
    permittedUse2:     { en: 'Generate ESG reports and share them internally with your team or management.', es: 'Genera reportes ESG y compártelos internamente con tu equipo o gerencia.' },
    permittedUse3:     { en: 'Input accurate and truthful operational data to the best of your knowledge.', es: 'Ingresa datos operativos precisos y veraces según tu mejor conocimiento.' },
    permittedUse4:     { en: 'Integrate with third-party systems (POS, PMS, CRM) using authorized API connections.', es: 'Integra con sistemas de terceros (POS, PMS, CRM) usando conexiones API autorizadas.' },
    prohibited1:       { en: 'Reverse engineering, decompiling, or attempting to extract the source code of the platform.', es: 'Ingeniería inversa, descompilación o intento de extraer el código fuente de la plataforma.' },
    prohibited2:       { en: 'Uploading malicious code, viruses, or attempting to disrupt platform availability.', es: 'Subir código malicioso, virus o intentar interrumpir la disponibilidad de la plataforma.' },
    prohibited3:       { en: 'Using the platform for any unlawful purpose or to violate any applicable regulations.', es: 'Usar la plataforma para cualquier propósito ilegal o violar cualquier regulación aplicable.' },
    prohibited4:       { en: 'Reselling, sublicensing, or redistributing access to the platform without written consent.', es: 'Revender, sublicenciar o redistribuir acceso a la plataforma sin consentimiento por escrito.' },
    prohibited5:       { en: 'Submitting false, misleading, or fraudulent data into the system.', es: 'Enviar datos falsos, engañosos o fraudulentos al sistema.' },
